15	    14	/**
16	    15	 * Assigns the owner's {@code customerCode}, formatted {@code <REGION>-<HASH8>} where
17	    16	 * REGION is the region code derived from the postcode (the shared derivation in
18	    17	 * {@link Localities#region(String, String)}, postcode-range first, city fallback) and
19	    18	 * HASH8 is the first eight upper-case hex characters of the SHA-256 digest over the
20	    19	 * normalized telephone concatenated with the last name. The telephone is already in its
21	    20	 * normalized E.164 form by this step (see {@link ValidateOwnerFields}).
22	    21	 *
23	    22	 * <p>The base code is a pure function of the owner's identity, but two distinct owners can
24	    23	 * still hash to the same {@code <REGION>-<HASH8>}. When the computed code collides with an
25	    24	 * existing owner's {@code customerCode}, {@code -<n>} is appended with the smallest
26	    25	 * {@code n} of 2 or more that makes it unique. The new owner is not yet saved, so it is
27	    26	 * not among the existing owners scanned here.
28	    27	 */
29	    28	public class AssignCustomerCode {
30	    29	
31	    30	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
32	    31	        String region = Localities.region(owner.getCity(), owner.getPostcode());
33	    32	        String hash8 = sha256Hex8(owner.getTelephone() + owner.getLastName());
34	    33	        String base = region + "-" + hash8;
35	    34	
36	    35	        Set<String> taken = new HashSet<>();
37	    36	        for (Owner existing : ownerRepository.findAll()) {
38	    37	            if (existing.getCustomerCode() != null) {
39	    38	                taken.add(existing.getCustomerCode());
40	    39	            }
41	    40	        }
42	    41	
43	    42	        String code = base;
44	    43	        for (int n = 2; taken.contains(code); n++) {
45	    44	            code = base + "-" + n;
46	    45	        }
47	    46	        owner.setCustomerCode(code);
48	    47	    }
49	    48	
50	    49	    /** The first eight upper-case hex characters of the SHA-256 digest of {@code s}. */
51	    50	    private static String sha256Hex8(String s) {
52	    51	        byte[] digest;
53	    52	        try {
54	    53	            digest = MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8));
55	    54	        }
56	    55	        catch (NoSuchAlgorithmException ex) {
57	    56	            throw new IllegalStateException("SHA-256 not available", ex);
58	    57	        }
59	    58	        StringBuilder sb = new StringBuilder(8);
60	    59	        for (int i = 0; sb.length() < 8; i++) {
61	    60	            sb.append(String.format("%02X", digest[i]));
62	    61	        }
63	    62	        return sb.substring(0, 8);
64	    63	    }
65	    64	}
