113	    10	import net.officefloor.plugin.variable.Out;
114	    11	import org.springframework.samples.petclinic.mapper.Localities;
115	    12	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
116	    13	import org.springframework.samples.petclinic.rest.escalation.MissingFieldsException;
117	    14	import org.springframework.web.bind.annotation.RequestBody;
118	    15	
119	    16	/**
120	    17	 * Rejects a create request that is missing or blank in any required owner field, so an
121	    18	 * incomplete body is a 400 whose {@code errors} array names each offending field. Also
122	    19	 * normalizes the telephone to E.164 form (see {@link TelephoneE164}), republishing the
123	    20	 * normalized value so it is stored and returned as {@code telephone}; a telephone that
124	    21	 * cannot form a valid E.164 number is a 400 too.
125	    22	 * The optional {@code email} is validated only when present: a syntactically invalid
126	    23	 * address is a 400, an otherwise-valid address whose domain is on the disposable-domain
127	    24	 * blocklist is a 400, otherwise it is normalized to lower-case and republished so it is
128	    25	 * stored and returned lower-cased.
129	    26	 * The address may be supplied in a structured form ({@code addressLine1} plus an optional
130	    27	 * {@code addressLine2}) or as the flat {@code address}; the structured form is preferred when a
131	    28	 * non-blank {@code addressLine1} is present. Whichever fields are supplied are normalized (see
132	    29	 * {@link AddressNormalizer}) and republished, and the stored/returned {@code address} is the
133	    30	 * composed value (normalized {@code addressLine1}, plus a space and the normalized
134	    31	 * {@code addressLine2} when present) falling back to the normalized flat {@code address}. An owner
135	    32	 * that supplies an address in neither form is a required-field 400.
136	    33	 * The optional {@code registrationDate} is validated only when present: a date later than
137	    34	 * the server's current date is a 400.
138	    35	 * Runs first and republishes the body as a variable for {@link BuildOwner}.
139	    36	 */
140	    37	public class ValidateOwnerFields {
141	    38	
142	    39	    /** Syntactic email check: one '@', non-empty local part, and a dotted domain. */
143	    40	    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
144	    41	
145	    42	    /** Disposable email domains that are rejected: a syntactically valid address whose domain
146	    43	     *  (lower-cased) is listed here is a 400. */
147	    44	    private static final Set<String> DISPOSABLE_DOMAINS =
148	    45	            Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
149	    46	
150	    47	    /** A well-formed postcode is exactly four digits. */
151	    48	    private static final Pattern POSTCODE = Pattern.compile("^[0-9]{4}$");
152	    49	
153	    50	    /** Region -> inclusive 4-digit postcode range {low, high}. A city whose region is not
154	    51	     *  listed (derives "UNKNOWN") accepts any well-formed 4-digit postcode. */
155	    52	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
156	    53	            "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
157	    54	
158	    55	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
159	    56	            throws MissingFieldsException {
160	    57	        List<String> errors = new ArrayList<>();
161	    58	        if (isBlank(request.getFirstName())) {
162	    59	            errors.add("firstName");
163	    60	        }
164	    61	        if (isBlank(request.getLastName())) {
165	    62	            errors.add("lastName");
166	    63	        }
167	    64	        applyAddress(request, errors);
168	    65	        if (isBlank(request.getCity())) {
169	    66	            errors.add("city");
170	    67	        }
171	    68	        String telephone = TelephoneE164.normalize(request.getTelephone());
172	    69	        if (telephone == null) {
173	    70	            errors.add("telephone");
174	    71	        }
175	    72	        else {
176	    73	            request.setTelephone(telephone);
177	    74	        }
178	    75	        String email = request.getEmail();
179	    76	        if (email != null && !email.isBlank()) {
180	    77	            String normalized = email.trim().toLowerCase();
181	    78	            if (!EMAIL.matcher(normalized).matches()) {
182	    79	                errors.add("email");
183	    80	            }
184	    81	            else if (DISPOSABLE_DOMAINS.contains(normalized.substring(normalized.indexOf('@') + 1))) {
185	    82	                errors.add("email");
186	    83	            }
187	    84	            else {
188	    85	                request.setEmail(normalized);
189	    86	            }
190	    87	        }
191	    88	        // Postcode is optional; validated only when present. A malformed (non-4-digit) postcode
192	    89	        // is a 400, and a well-formed postcode outside its city's region range is a 400 too.
193	    90	        // A city with no known region accepts any 4-digit postcode.
194	    91	        String postcode = request.getPostcode();
195	    92	        if (postcode != null && !postcode.isBlank()) {
196	    93	            String trimmed = postcode.trim();
197	    94	            if (!POSTCODE.matcher(trimmed).matches() || !inRegionRange(request.getCity(), trimmed)) {
198	    95	                errors.add("postcode");
199	    96	            }
200	    97	            else {
201	    98	                request.setPostcode(trimmed);
202	    99	            }
203	   100	        }
204	   101	        // registrationDate is optional; validated only when present. A date later than the
205	   102	        // server's current date is a 400 — an owner cannot be registered in the future.
206	   103	        LocalDate registrationDate = request.getRegistrationDate();
207	   104	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
208	   105	            errors.add("registrationDate");
209	   106	        }
210	   107	        if (!errors.isEmpty()) {
211	   108	            throw new MissingFieldsException(errors);
212	   109	        }
213	   110	        validated.set(request);
214	   111	    }
215	   112	
216	   113	    /**
217	   114	     * Normalizes whichever address fields are supplied and republishes them, preferring the
218	   115	     * structured form. A non-blank {@code addressLine1} (with an optional {@code addressLine2})
219	   116	     * wins over the flat {@code address}; either form satisfies the address requirement. The
220	   117	     * stored/returned {@code address} is the composed value: the normalized {@code addressLine1},
221	   118	     * plus a single space and the normalized {@code addressLine2} when present, falling back to the
222	   119	     * normalized flat {@code address}. An owner supplying neither is a required-field 400.
223	   120	     */
224	   121	    private static void applyAddress(OwnerFieldsDto request, List<String> errors) {
225	   122	        String line1 = AddressNormalizer.normalize(request.getAddressLine1());
226	   123	        String line2 = AddressNormalizer.normalize(request.getAddressLine2());
227	   124	        String flat = AddressNormalizer.normalize(request.getAddress());
228	   125	        if (!line1.isEmpty()) {
229	   126	            request.setAddressLine1(line1);
230	   127	            String composed = line1;
231	   128	            if (!line2.isEmpty()) {
232	   129	                request.setAddressLine2(line2);
233	   130	                composed = line1 + " " + line2;
234	   131	            }
235	   132	            else {
236	   133	                request.setAddressLine2(null);
237	   134	            }
238	   135	            request.setAddress(composed);
239	   136	        }
240	   137	        else if (!flat.isEmpty()) {
241	   138	            request.setAddress(flat);
242	   139	        }
243	   140	        else {
244	   141	            errors.add("address");
245	   142	        }
246	   143	    }
247	   144	
248	   145	    private static boolean isBlank(String value) {
249	   146	        return value == null || value.isBlank();
250	   147	    }
251	   148	
252	   149	    /** True when the 4-digit {@code postcode} is acceptable for the city's region: either the
253	   150	     *  city has no known region (accepts any 4-digit postcode) or the postcode falls within the
254	   151	     *  region's inclusive range. */
255	   152	    private static boolean inRegionRange(String city, String postcode) {
256	   153	        if (isBlank(city)) {
257	   154	            return true; // no city yet: no region constraint (the missing city is flagged separately)
258	   155	        }
259	   156	        int[] range = REGION_POSTCODES.get(Localities.region(city));
260	   157	        if (range == null) {
261	   158	            return true;
262	   159	        }
263	   160	        int value = Integer.parseInt(postcode);
264	   161	        return value >= range[0] && value <= range[1];
265	   162	    }
266	   163	}
