283	    15	 * @param seq             monotonically increasing sequence number across creates
284	    16	 * @param ownerId         the generated owner id
285	    17	 * @param customerCode    the owner's current primary identifier (see above)
286	    18	 * @param membershipLevel the owner's assigned membership level
287	    19	 * @param event           the event marker, always {@link #OWNER_CREATED}
288	    20	 */
289	    21	public record OwnerCreatedEvent(long seq, Integer ownerId, String customerCode,
290	    22	        Integer membershipLevel, String event) {
291	    23	
292	    24	    /** Event marker for a successful owner create. */
293	    25	    public static final String OWNER_CREATED = "OWNER_CREATED";
294	    26	
295	    27	    /**
296	    28	     * The owner's current primary identifier. Today the {@code customerCode}; when the
297	    29	     * customerCode is unified into the {@code memberId} this method returns the memberId,
298	    30	     * and the emitted event carries that instead — the one place that changes.
299	    31	     */
300	    32	    public static String primaryIdentifier(Owner owner) {
