345	     1	package org.springframework.samples.petclinic.mapper;
346	     2	
347	     3	/**
348	     4	 * Computes the Luhn check digit over the digits contained in a string. Non-digit
349	     5	 * characters are ignored, so it applies directly to a formatted customerCode.
350	     6	 * Kept as a plain static helper (not a mapper method) so MapStruct does not treat
351	     7	 * it as an implicit mapping method.
352	     8	 */
353	     9	public final class CheckDigits {
354	    10	
355	    11	    private CheckDigits() {
356	    12	    }
357	    13	
358	    14	    /**
359	    15	     * The Luhn check digit (0-9) over the digits contained in {@code s}. Returns null
360	    16	     * when {@code s} is null so the field is omitted for owners without a customerCode.
361	    17	     */
362	    18	    public static Integer luhn(String s) {
363	    19	        if (s == null) {
364	    20	            return null;
365	    21	        }
366	    22	        int sum = 0;
367	    23	        boolean dbl = true;
368	    24	        for (int i = s.length() - 1; i >= 0; i--) {
369	    25	            char c = s.charAt(i);
370	    26	            if (c < '0' || c > '9') {
371	    27	                continue;
372	    28	            }
373	    29	            int d = c - '0';
374	    30	            if (dbl) {
375	    31	                d *= 2;
376	    32	                if (d > 9) {
377	    33	                    d -= 9;
378	    34	                }
379	    35	            }
380	    36	            sum += d;
381	    37	            dbl = !dbl;
382	    38	        }
383	    39	        return (10 - (sum % 10)) % 10;
384	    40	    }
385	    41	}
