425	     7	/**
426	     8	 * Derives an owner's canonical locality (region). The postcode range is preferred:
427	     9	 * a postcode within a known region range decides the region and disambiguates cities
428	    10	 * that share a name. Only when the postcode is absent or in no known range does the
429	    11	 * fixed city-to-region table apply. Kept as a plain static helper (not a mapper
430	    12	 * method) so MapStruct does not treat it as an implicit String-to-String mapping method.
431	    13	 */
432	    14	public final class Localities {
433	    15	
434	    16	    /** City -> canonical region; anything not listed derives locality "UNKNOWN". */
435	    17	    private static final Map<String, String> CITY_REGION = Map.of(
436	    18	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
437	    19	
438	    20	    /** Region -> inclusive 4-digit postcode range {low, high}. */
439	    21	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
440	    22	            "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
441	    23	
442	    24	    /** Region -> IANA timezone name; anything not listed derives a null timezone. */
443	    25	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
444	    26	            "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
445	    27	
446	    28	    private Localities() {
447	    29	    }
448	    30	
449	    31	    /** The canonical region for the given city, or "UNKNOWN" when the city is not in the table. */
450	    32	    public static String region(String city) {
451	    33	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
452	    34	    }
453	    35	
454	    36	    /**
455	    37	     * The canonical region. The postcode range is looked up first; if the postcode is
456	    38	     * absent or in no known range, falls back to the city-to-region table. Returns
457	    39	     * "UNKNOWN" when neither resolves.
458	    40	     */
459	    41	    public static String region(String city, String postcode) {
460	    42	        String byPostcode = regionByPostcode(postcode);
