535	    15	    /**
536	    16	     * The membership points: start at 0, add 2 when an email is present, add 1 when
537	    17	     * namesakeCount is 0, add 2 for a household of 3 or more, add 3 for a tenure of at least
538	    18	     * one elapsed fiscal year. A newly created owner has zero tenure, so it cannot earn the
539	    19	     * tenure points on creation.
540	    20	     */
541	    21	    public static int points(Owner owner) {
542	    22	        return points(owner, owner.getHouseholdSize() == null ? 0 : owner.getHouseholdSize());
543	    23	    }
544	    24	
545	    25	    /**
546	    26	     * The membership points as {@link #points(Owner)}, but with the household-of-3 bonus decided
547	    27	     * by the supplied {@code householdSize} instead of the owner's own stored size. Used to value
548	    28	     * an existing member as part of the household the new owner is joining, whose current size the
549	    29	     * whole household now shares.
550	    30	     */
551	    31	    public static int points(Owner owner, int householdSize) {
552	    32	        int points = 0;
553	    33	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
554	    34	            points += 2;
555	    35	        }
556	    36	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
557	    37	            points += 1;
558	    38	        }
559	    39	        if (householdSize >= 3) {
560	    40	            points += 2;
561	    41	        }
562	    42	        if (tenureFiscalYears(owner) >= 1) {
