613	     3	import java.time.LocalDate;
614	     4	import java.time.Month;
615	     5	
616	     6	/**
617	     7	 * Derives fiscal-year values from a date. The fiscal year starts on 1 July, so July to
618	     8	 * December belong to the fiscal year named by that same calendar year and January to June
619	     9	 * belong to the fiscal year that started in the previous calendar year. Kept as a plain
620	    10	 * static helper so the single rule is shared by the response mapper, the membership points
621	    11	 * and the create audit line.
622	    12	 */
623	    13	public final class FiscalYears {
624	    14	
625	    15	    private FiscalYears() {
626	    16	    }
627	    17	
628	    18	    /**
629	    19	     * The calendar year in which the fiscal year containing {@code date} began.
630	    20	     */
631	    21	    public static int startYear(LocalDate date) {
632	    22	        int year = date.getYear();
633	    23	        return date.getMonthValue() >= Month.JULY.getValue() ? year : year - 1;
634	    24	    }
635	    25	
636	    26	    /**
637	    27	     * The fiscal year label {@code 'FY<YY>'} for {@code date}, where YY is the last two
638	    28	     * digits of {@link #startYear(LocalDate)}.
639	    29	     */
640	    30	    public static String label(LocalDate date) {
641	    31	        return String.format("FY%02d", startYear(date) % 100);
642	    32	    }
643	    33	
644	    34	    /**
645	    35	     * Whole fiscal years elapsed between {@code from} and {@code to}, i.e. the number of
646	    36	     * 1 July boundaries crossed. Zero when both dates fall in the same fiscal year.
647	    37	     */
648	    38	    public static int elapsed(LocalDate from, LocalDate to) {
649	    39	        return startYear(to) - startYear(from);
650	    40	    }
651	    41	}
