     6	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
     7	
     8	/**
     9	 * The consolidated duplicate check, rejecting a create with 409 when the new owner's whole
    10	 * {@code identityKey} (see {@link OwnerIdentity}, the SHA-256 hex over
    11	 * {@code normalizedTelephone|lowerEmail|soundex(lastName)}) equals an existing, non-deleted owner's.
    12	 *
    13	 * <p>This single identity key is now the whole of duplicate detection: the separate household
    14	 * duplicate block (keyed on the computed {@code householdId}) no longer applies. Because the
    15	 * telephone is part of the key, two owners sharing {@code soundex(lastName)} and postcode but with
    16	 * different telephones have different keys and are <em>not</em> rejected here — they are created as a
    17	 * soft match (see {@link AssignPossibleDuplicate}). Only an exact whole-key match collides.
    18	 *
    19	 * <p>Soft-deleted owners are ignored, so a re-create after a delete succeeds. The blocklisted
    20	 * email-domain rejection runs earlier (see {@code ValidateOwnerFields}), before this step. The new
    21	 * owner is not yet saved, so it is not among the existing owners compared here.
    22	 */
    23	public class EnsureUniqueIdentity {
    24	
    25	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
    26	            throws DuplicateIdentityException {
    27	        String identityKey = OwnerIdentity.of(owner);
    28	        for (Owner existing : ownerRepository.findAll()) {
    29	            if (existing.isDeleted()) {
    30	                continue; // a soft-deleted owner no longer blocks a create
    31	            }
    32	            if (identityKey.equals(OwnerIdentity.of(existing))) {
    33	                throw new DuplicateIdentityException(identityKey);
    34	            }
    35	        }
    36	    }
    37	}

