    10	/**
    11	 * Assigns the owner's stable, shared {@code householdId}, derived deterministically from the
    12	 * household's identity — its {@code lastName} (compared case-insensitively with collapsed
    13	 * whitespace) and {@code postcode}. The value is the first 12 hex characters of
    14	 * SHA-256 over {@code normalizedLastName + '|' + postcode}, so every owner with the same
    15	 * lastName and postcode computes the same identifier automatically — no lookup or backfill of
    16	 * other owners is needed.
    17	 *
    18	 * <p>The identifier is computed for every create with a postcode, independent of
    19	 * {@code sharesHousehold}: sharing a household is now an intrinsic consequence of the
    20	 * lastName/postcode pair, and {@code sharesHousehold} only governs whether a would-be household
    21	 * duplicate is blocked (see {@link EnsureUniqueIdentity}). An owner without a postcode has no
    22	 * household, so its {@code householdId} is left null.
    23	 *
    24	 * <p>Runs after {@code build}, so the new Owner entity exists but is not yet saved.
    25	 */
    26	public class AssignHousehold {
    27	
    28	    public void service(@Val Owner owner) {
    29	        String postcode = owner.getPostcode();
    30	        if (postcode == null || postcode.isBlank()) {
    31	            return; // no household without a postcode
    32	        }
    33	        String lastName = normalize(owner.getLastName());
    34	        owner.setHouseholdId(householdId(lastName, postcode));
    35	    }
    36	
    37	    /** Stable 12-hex-char identifier for a household: the first 12 hex characters of SHA-256 over
    38	     *  the normalized lastName and postcode, so every member of the same household computes the
    39	     *  same value. */
    40	    private static String householdId(String lastName, String postcode) {
    41	        return sha256hex(lastName + "|" + postcode).substring(0, 12);
    42	    }
    43	
    44	    private static String sha256hex(String value) {
    45	        try {
    46	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
    47	            StringBuilder sb = new StringBuilder(digest.length * 2);
    48	            for (byte b : digest) {
    49	                sb.append(String.format("%02x", b));
    50	            }
    51	            return sb.toString();
    52	        }
    53	        catch (Exception e) {
    54	            throw new RuntimeException(e);
    55	        }
    56	    }
    57	
    58	    /** Case-insensitive with collapsed whitespace: trim, fold internal whitespace runs to a
    59	     *  single space, and lower-case. */
    60	    private static String normalize(String value) {
    61	        if (value == null) {
    62	            return "";
    63	        }
    64	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    65	    }
    66	}

